#!/usr/bin/env python3
"""Derive and build the broadcast viewer's symbol font (#415).

JetBrains Mono lacks some symbols agents draw (⏺ ⏸ ✳ ⎿, braille spinners), and
iPad Safari falls back to Apple Color Emoji for several of them. This keeps a
list of those code points (symbols.txt) and subsets Noto Sans Symbols 2 to
exactly that list, every glyph moved into JetBrains Mono's cell so a symbol
keeps the column width Couch counts. Development-time only; needs
`pip install fonttools brotli`. See VENDOR.md.

  symbols.py scan  NOTO_TTF FILE...  # add symbols found in FILEs to symbols.txt
  symbols.py build NOTO_TTF          # write the subset, print its unicode-range
"""
import hashlib
import os
import sys
import unicodedata

from fontTools.pens.recordingPen import DecomposingRecordingPen
from fontTools.pens.transformPen import TransformPen
from fontTools.pens.ttGlyphPen import TTGlyphPen
from fontTools.subset import Options, Subsetter
from fontTools.ttLib import TTFont

HERE = os.path.dirname(os.path.abspath(__file__))
LIST = os.path.join(HERE, "symbols.txt")
OUT = os.path.join(HERE, "NotoSansSymbols2-Couch.woff")
JBM = os.path.join(HERE, "JetBrainsMono-Regular.woff2")
# unhinted/ttf/NotoSansSymbols2-Regular.ttf from NotoSansSymbols2-v2.008.zip.
NOTO_SHA256 = "c4a0a80f0041ce4be81e2478faad22776d23edb98ae3f0d19bd37044820ecf9d"
MARGIN = 30  # font units kept clear on each side of a glyph scaled to fit


def noto(path):
    with open(path, "rb") as f:
        if hashlib.sha256(f.read()).hexdigest() != NOTO_SHA256:
            sys.exit(f"{path}: not the pinned Noto Sans Symbols 2 (see VENDOR.md)")
    return TTFont(path, recalcTimestamp=False)


def read_list():
    if not os.path.exists(LIST):
        return set()
    with open(LIST, encoding="utf-8") as f:
        return {int(l.split()[0][2:], 16) for l in f if l.startswith("U+")}


def wanted(cp, jbm):
    cat = unicodedata.category(chr(cp))
    # Symbols and punctuation only, never letters or digits (prose in other
    # scripts). Wide characters are emoji by default, as in the operator's
    # terminal; they keep their emoji.
    return (cp >= 0x80 and cp not in jbm and (cat[0] in "SP" or cat == "No")
            and unicodedata.east_asian_width(chr(cp)) not in "WF")


def scan(noto_path, files):
    jbm, cmap = TTFont(JBM).getBestCmap(), noto(noto_path).getBestCmap()
    found = set()
    for path in files:
        with open(path, "rb") as f:
            found |= {ord(c) for c in set(f.read().decode("utf-8", "replace"))}
    found = {cp for cp in found if wanted(cp, jbm)}
    for cp in sorted(found - set(cmap)):
        print(f"not in Noto Sans Symbols 2, skipped: U+{cp:04X} {chr(cp)}", file=sys.stderr)
    cps = read_list() | (found & set(cmap))
    with open(LIST, "w", encoding="utf-8") as f:
        f.write("# Generated by symbols.py scan; additive, edit by hand to remove.\n")
        for cp in sorted(cps):
            f.write(f"U+{cp:04X} {chr(cp)} {unicodedata.name(chr(cp), '')}\n")


def build(noto_path):
    cps = sorted(read_list())
    jbm = TTFont(JBM)
    cell, upm = jbm["hmtx"]["space"][0], jbm["head"].unitsPerEm
    font = noto(noto_path)
    assert font["head"].unitsPerEm == upm, "units per em differ from JetBrains Mono"
    opts = Options()
    opts.layout_features, opts.hinting, opts.notdef_outline = [], False, True
    sub = Subsetter(opts)
    sub.populate(unicodes=cps)
    sub.subset(font)
    glyf, hmtx, glyphs = font["glyf"], font["hmtx"], font.getGlyphSet()
    outlines = {}
    for name in font.getGlyphOrder():
        outlines[name] = DecomposingRecordingPen(glyphs)
        glyphs[name].draw(outlines[name])
    for name in font.getGlyphOrder():
        adv, _ = hmtx[name]
        g = glyf[name]
        dx, scale, cx, cy = (cell - adv) / 2, 1.0, cell / 2, 0
        if g.numberOfContours:
            g.recalcBounds(glyf)
            # Keep the glyph where its own advance box put it, centred in the
            # cell (braille dots stay in place); shrink it only if it overflows.
            width = g.xMax - g.xMin
            if g.xMin + dx < MARGIN or g.xMax + dx > cell - MARGIN:
                scale = min(1.0, (cell - 2 * MARGIN) / width)
                dx = cx - (g.xMin + g.xMax) / 2
                cy = (g.yMin + g.yMax) / 2
            pen = TTGlyphPen(None)
            outlines[name].replay(TransformPen(pen, (scale, 0, 0, scale,
                                      cx - scale * (cx - dx), cy - scale * cy)))
            glyf[name] = pen.glyph()
            glyf[name].recalcBounds(glyf)
        hmtx[name] = (cell, glyf[name].xMin if glyf[name].numberOfContours else 0)
    font["hhea"].advanceWidthMax = cell
    font.flavor = "woff"
    font.save(OUT)
    print("unicode-range: " + ", ".join(f"U+{cp:04X}" for cp in cps) + ";")


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "scan":
        scan(sys.argv[2], sys.argv[3:])
    elif len(sys.argv) == 3 and sys.argv[1] == "build":
        build(sys.argv[2])
    else:
        sys.exit(__doc__)
